function:notify_new_block():
CREATE OR REPLACE FUNCTION public.notify_new_block()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    PERFORM pg_notify(
            'new_block',
            json_build_object(
                    'block_number', NEW.block_number,
                    'block_hash', NEW.block_hash,
                    'timestamp', NEW.timestamp
            )::text
            );
    RETURN NEW;
END;
$function$
